import pandas as pd
import numpy as np

# Test 1: GroupBy aggregations with Float64 dtype and skipna=False
operations = ['sum', 'mean', 'std', 'var', 'sem', 'skew', 'kurt', 'prod']

for op in operations:
    try:
        df = pd.DataFrame({
            'A': [1]*5,
            'B': pd.Series([1.0, 2.0, 3.0, 4.0, pd.NA], dtype='Float64')
        })
        result = getattr(df.groupby('A')['B'], op)(skipna=False)
        probe(f"DataFrame({{'A':[1]*5,'B':Series([1.0,2.0,3.0,4.0,pd.NA],dtype='Float64')}}).groupby('A')['B'].{op}(skipna=False)", result)
    except Exception as e:
        probe_exception(f"DataFrame({{'A':[1]*5,'B':Series([1.0,2.0,3.0,4.0,pd.NA],dtype='Float64')}}).groupby('A')['B'].{op}(skipna=False)", e)

# Test 2: GroupBy aggregations with FloatingArray containing NaN and skipna=True
operations2 = ['sum', 'mean', 'std', 'var', 'sem', 'skew', 'kurt', 'prod']

for op in operations2:
    try:
        ser = pd.Series(pd.arrays.FloatingArray(
            np.array([1.0, 2.0, 3.0, 4.0, np.nan]),
            np.array([False]*5)
        ))
        df = pd.DataFrame({'A': [1]*5, 'B': ser})
        result = getattr(df.groupby('A')['B'], op)(skipna=True)
        probe(f"ser = Series(pd.arrays.FloatingArray(np.array([1.0,2.0,3.0,4.0,np.nan]), np.array([False]*5))); DataFrame({{'A':[1]*5,'B':ser}}).groupby('A')['B'].{op}(skipna=True)", result)
