        probe_exception(f"ser = Series(pd.arrays.FloatingArray(np.array([1.0,2.0,3.0,4.0,np.nan]), np.array([False]*5))); DataFrame({{'A':[1]*5,'B':ser}}).groupby('A')['B'].{op}(skipna=True)", e)

